<?php require_once __DIR__.'/config.php'; require_admin(); $page_title='Services & Pricing'; require_once __DIR__.'/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; if($action==='add'||$action==='edit'){ $id=(int)($_POST['id']??0);$data=[trim($_POST['category']),trim($_POST['service_item']),trim($_POST['price_label']),$_POST['default_price']!==''?(float)$_POST['default_price']:null,trim($_POST['notes'])]; if($data[0]===''||$data[1]===''){flash('Category and service item are required.','error');}elseif($action==='add'){db()->prepare('INSERT INTO services(category,service_item,price_label,default_price,notes) VALUES(?,?,?,?,?)')->execute($data);flash('Service added.');}else{db()->prepare('UPDATE services SET category=?,service_item=?,price_label=?,default_price=?,notes=? WHERE id=?')->execute([...$data,$id]);flash('Service updated.');} header('Location: services.php');exit;} if($action==='toggle') {db()->prepare('UPDATE services SET active=1-active WHERE id=?')->execute([(int)$_POST['id']]);flash('Service status updated.');header('Location: services.php');exit;}}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM services WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=db()->query('SELECT * FROM services ORDER BY category,service_item')->fetchAll(); ?>
<div class="list-head"><div><span>ADMINISTRATION</span><h2>Services & pricing</h2><p>Manage the services available for payment records.</p></div><button class="primary" onclick="document.getElementById('service-modal').showModal()">＋ Add Service</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Service Item</th><th>Pricing</th><th>Notes</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="tag"><?=e($r['category'])?></span></td><td><strong><?=e($r['service_item'])?></strong></td><td class="amount"><?=e($r['price_label'])?></td><td><?=e($r['notes'])?></td><td><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="status <?=$r['active']?'on':'off'?>"><?=$r['active']?'Active':'Inactive'?></button></form></td><td><a class="text-link" href="services.php?edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></div>
<dialog id="service-modal" <?= $edit?'open':'' ?>><form method="post" class="modal-form"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><div class="modal-title"><h2><?=$edit?'Edit':'Add'?> service</h2><button type="button" onclick="this.closest('dialog').close()">×</button></div><label>Category<input name="category" value="<?=e($edit['category']??'')?>" required></label><label>Service Item<input name="service_item" value="<?=e($edit['service_item']??'')?>" required></label><label>Pricing label<input name="price_label" value="<?=e($edit['price_label']??'')?>" placeholder="e.g. ₱1,500 – ₱2,500"></label><label>Suggested amount<input type="number" step="0.01" min="0" name="default_price" value="<?=e($edit['default_price']??'')?>" placeholder="Optional"></label><label>Notes<textarea name="notes"><?=e($edit['notes']??'')?></textarea></label><div class="form-actions"><button type="button" class="secondary" onclick="this.closest('dialog').close()">Cancel</button><button class="primary">Save service</button></div></form></dialog><?php require __DIR__.'/footer.php';
